<script setup lang="ts">import {z} from 'zod';definePageMeta({middleware:'auth'});const {request}=useApi();const customers=ref<any[]>([]);const products=ref<any[]>([]);const customerId=ref('');const rows=ref([{product_id:'',quantity:1}]);const errors=ref<Record<string,string[]>>({});const submitting=ref(false);onMounted(async()=>{const [c,p]=await Promise.all([request<any>('/customers?per_page=100'),request<any>('/products?per_page=100')]);customers.value=c.data;products.value=p.data});const total=computed(()=>rows.value.reduce((sum,r)=>{const p=products.value.find(x=>String(x.id)===r.product_id);return sum+(p?Number(p.price)*r.quantity:0)},0));function add(){rows.value.push({product_id:'',quantity:1})}async function submit(){const schema=z.object({customer_id:z.string().uuid(),items:z.array(z.object({product_id:z.string().min(1),quantity:z.number().int().positive()})).min(1)});const parsed=schema.safeParse({customer_id:customerId.value,items:rows.value});if(!parsed.success){errors.value={'form':['Lengkapi pelanggan dan item pesanan']};return}submitting.value=true;errors.value={};const key=crypto.randomUUID();try{await request('/orders',{method:'POST',headers:{'Idempotency-Key':key},body:{customer_id:customerId.value,items:rows.value.map(r=>({product_id:Number(r.product_id),quantity:r.quantity}))}});await navigateTo('/orders')}catch(e:any){errors.value=e.data?.errors||{form:[e.data?.message||'Order gagal dibuat']}}finally{submitting.value=false}}</script><template><section class="max-w-4xl"><h1 class="text-2xl font-bold mb-5">Create Order</h1><label class="block mb-4">Customer<select v-model="customerId" class="block border p-2 rounded w-full"><option value="">Select customer</option><option v-for="c in customers" :value="c.id">{{c.customer_name}}</option></select></label><div v-for="(row,i) in rows" :key="i" class="grid grid-cols-3 gap-3 mb-3"><select v-model="row.product_id" class="border p-2 rounded"><option value="">Product</option><option v-for="p in products" :value="String(p.id)">{{p.product_name}} — Rp {{Number(p.price).toLocaleString('id-ID')}}</option></select><input v-model.number="row.quantity" type="number" min="1" class="border p-2 rounded"/><button type="button" @click="rows.splice(i,1)" :disabled="rows.length===1">Remove</button></div><button @click="add" class="text-blue-700">+ Add item</button><h2 class="text-xl font-bold my-5">Total: Rp {{total.toLocaleString('id-ID')}}</h2><p v-for="(v,k) in errors" class="text-red-600">{{k}}: {{v.join(', ')}}</p><button @click="submit" :disabled="submitting" class="bg-blue-700 text-white px-5 py-3 rounded">{{submitting?'Submitting…':'Submit order'}}</button></section></template>
